import{_ as o,c as r,o as a,a2 as e}from"./chunks/framework.CHomSxuB.js";const g=JSON.parse('{"title":"足球信号雷达","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/index.md","filePath":"足球信号雷达/index.md"}'),d={name:"足球信号雷达/index.md"};function n(s,t,h,l,u,i){return a(),r("div",null,t[0]||(t[0]=[e('<h1 id="足球信号雷达" tabindex="-1">足球信号雷达 <a class="header-anchor" href="#足球信号雷达" aria-label="Permalink to &quot;足球信号雷达&quot;">​</a></h1><blockquote><p>一句话：<strong>一个只研究赔率信号、不碰下注的验证体系</strong>——把&quot;赔率背后谁在动、动得对不对&quot;拆成可检验的信号， 用样本外（OOS）时间换证据，允许并预期&quot;信号失效&quot;。 2026-09-01 起项目已整体移除下注相关代码，只保留<strong>信号研究</strong>与<strong>读盘展示</strong>两条腿。</p></blockquote><p>本板块与 <a href="/A股量化验证/">A股量化验证</a> 是同一套统计纪律在不同市场的落地： A 股验证&quot;涨停生态里的盘面传言&quot;，足球这边验证&quot;赔率变动里的市场信号&quot;——都是<strong>先冻结规则 → 只跑不调 → 如实落盘</strong>。</p><hr><h2 id="这个系列在做什么" tabindex="-1">这个系列在做什么 <a class="header-anchor" href="#这个系列在做什么" aria-label="Permalink to &quot;这个系列在做什么&quot;">​</a></h2><p>足球比赛的赔率里藏着三个问题：<strong>钱最终站在哪一边</strong>（方向）、<strong>大家是不是一条心</strong>（分歧）、<strong>临场有没有变</strong>（走势）。 V5 信号体系就是把这三点变成可统计的机器规则，然后逐场对账——每一条信号都要回答： &quot;触发后，不败方向到底命中了几成，相比赔率自己隐含的概率，多出来的部分扣不扣得住抽水。&quot;</p><p>方法论上的红线与 A 股一致：<strong>样本不足不评价、同一段历史挖参数=自欺、回测说的不算 OOS 说了才算</strong>。</p><hr><h2 id="战线状态-截至-2026-09-03" tabindex="-1">战线状态（截至 2026-09-03） <a class="header-anchor" href="#战线状态-截至-2026-09-03" aria-label="Permalink to &quot;战线状态（截至 2026-09-03）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td><strong>V5 信号体系</strong>（现役 4 信号）</td><td>方向级信号：定盘星背离 / 弱势弃守 ×2 / 准冷门震荡</td><td>🟡 OOS 观测中（逐日对账，判据线 50 场）</td></tr><tr><td>下注/资金层</td><td>胜平负分注、仓位、爆仓治理等</td><td>🔒 2026-09-01 整体移除（历史回放为负期望）</td></tr><tr><td>读盘与展示</td><td>每日竞彩报告站（公开）：市场状态红绿灯</td><td>🟢 运营中（展示层，非交易建议）</td></tr><tr><td>方法论沉淀</td><td>逐场结算 / 亚盘水位→概率 / 校准检验</td><td>📝 已沉淀（踩坑换来的，见方法论篇）</td></tr></tbody></table><blockquote><p>注：足球线当前<strong>不存在任何&quot;已转正可执行&quot;的生产信号</strong>。V5 四信号全部处于 OOS 观察期， 其中 SSS_VETO（定盘星背离）需累计 50+ 场且命中率 &gt;70% 才谈得上&quot;转正&quot;——目前 45/50 场，仍在积累。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇</th><th>内容</th></tr></thead><tbody><tr><td><a href="./1-V5信号体系与考决.html">1-V5信号体系与考决</a></td><td>V5 重建背景、2026-08-21 冻结考决（5 规则→4 活 1 死）、四信号语义与最新 OOS 状态</td></tr><tr><td><a href="./2-历史战线与下注层废弃.html">2-历史战线与下注层废弃</a></td><td>旧裁判层全链路回放结论、爆仓与过拟合教训、下注层整体移除决策</td></tr><tr><td><a href="./3-方法论沉淀.html">3-方法论沉淀</a></td><td>均值陷阱、逐场结算、亚盘水位→概率方法学、欧亚同向观测</td></tr><tr><td><a href="./4-读盘与展示.html">4-读盘与展示</a></td><td>公开报告站的定位收敛：从&quot;信号&quot;到&quot;市场状态观察仪&quot;</td></tr></tbody></table><hr><h2 id="证据语言约定" tabindex="-1">证据语言约定 <a class="header-anchor" href="#证据语言约定" aria-label="Permalink to &quot;证据语言约定&quot;">​</a></h2><ul><li>所有命中率/超额都标注 <strong>n（场次）与统计日期</strong>；样本不足只描述、不裁决；</li><li><strong>命中 = 不败方向命中</strong>（如&quot;主不败/客不败&quot;），不是&quot;赢盘/赢球&quot;，口径在每篇开头写明；</li><li><strong>超额 = 命中率 − 赔率隐含概率</strong>（去水后），衡量&quot;信号比市场多知道多少&quot;；</li><li>区分 <strong>证据（回测/OOS 数据）</strong> 与 <strong>叙事（机理推测）</strong>，后者不作结论引用。</li></ul><hr><blockquote><p>⚠️ <strong>免责声明</strong>：本系列仅作赔率数据与信号统计研究，<strong>不构成任何购买推荐</strong>。 参与竞彩请到线下合法渠道，理性娱乐；未满 18 周岁不得参与。</p></blockquote>',19)]))}const c=o(d,[["render",n]]);export{g as __pageData,c as default};
